  ('ng-nx14-sea-demon', 'Fin-Wings (2, back)', 20, 'Each. Small target: Called Shot, -3 to strike. Losing one or both cuts water travel and leaps by 10% and limits a hover to one melee round.', 4),
  ('ng-nx14-sea-demon', 'Arms (2)', 65, 'Each.', 5),
  ('ng-nx14-sea-demon', 'Forearm Weapons (2)', 15, 'Each. Small target: Called Shot, -3 to strike.', 6),
