  ('ng-nx14-sea-demon', 'NG-D2 Torpedo-Harpoon Cannon', 100, 'Small target: Called Shot, -3 to strike. Named the CDNX114 Sea Demon Cannon under Weapon Systems.', 10),
  ('ng-nx14-sea-demon', 'Main Body', 190, 'Reduced to zero, the armor shuts down completely and is useless.', 11),
