  ('ng-uelx49-silent-shadow', 'Hover Booster Jets (16; 4 each wing, 4 back, 2 per leg)', 10, 'Each. Tiny, black and hidden: Called Shot, -7 to strike.', 6),
  ('ng-uelx49-silent-shadow', 'Main Body', 190, 'Reduced to zero, the armor shuts down completely and is useless.', 7),
  ('ng-x40-storm-hammer', 'Head', 90, 'Small target: Called Shot, -4 to strike. Shielded from behind by the Weapon Cowl. Destroying it ends all optical and sensor enhancement and Robot Combat bonuses; underwater below 220 ft (67 m) the pilot takes 2D6 S.D.C./Hit Points per melee round and bonuses are halved.', 1),
  ('ng-x40-storm-hammer', 'Weapon Cowl', 150, 'Its loss silences both the particle beam turret and the rail gun, whose ammo drum it holds.', 2),
  ('ng-x40-storm-hammer', 'Particle Beam Turret (1, behind right shoulder)', 75, NULL, 3),
  ('ng-x40-storm-hammer', 'Shoulder Mini-Missile Launchers (2)', 40, 'Each.', 4),
  ('ng-x40-storm-hammer', 'Arms (2)', 80, 'Each.', 5),
  ('ng-x40-storm-hammer', 'Forearm Heavy Rail Gun (1, right arm)', 75, 'Small target: Called Shot, -4 to strike. If it is wrecked, the hand and forearm inside can be pulled free, with 35 M.D.C. of their own.', 6),
  ('ng-x40-storm-hammer', 'Forearm Cutter Platform (1, left arm)', 30, 'Small target: Called Shot, -4 to strike.', 7),
