INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-nx14-sea-demon', 1, 'CDNX114 Sea Demon Cannon (handheld; mini-torpedoes, harpoon and Vibro-Bayonet)', 'Mini-torpedo by type, most often high explosive (1D4x10 M.D.) or plasma (1D6x10 M.D.), 3 ft (0.9 m) blast radius; harpoon 2D4 M.D.; Vibro-Bayonet 3D6 M.D.', 1, 'Mini-torpedoes one mile (1.6 km); harpoon best at 200 ft (61 m) or less, -1 to strike per further 100 ft (30.5 m), 600 ft (183 m) at most; bayonet about 2 ft past the muzzle, roughly 5 ft (1.5 m) of reach', 'Each torpedo or harpoon shot counts as one melee attack', '21 mini-torpedoes and 12 harpoons on 800 ft (244 m) of line; the next harpoon is ready 15 seconds after a line is cut', NULL, 'Hunting and whaling, anti-sea monster and anti-ship, secondarily assault and defense. A huge two-barrelled gun, 198 lbs (89 kg), so heavy that even the suit handles it awkwardly; shoulder and waist straps hold it, the torpedoes sit at the rear and the cable drum under the middle, and its telescopic sight and laser targeting feed an eyepiece near the back. A struck whale or monster may tow gun and pilot along until the line is cut by a button; side handles let the pilot hang on for the ride. Torpedoes suit ships, submersibles, docks and slow monsters, being too slow to catch most power armor. The bayonet extends between the barrels for fighting or butchering; silver plating is 6,000 credits (gear row ng-nx14-sea-demon-bayonet-silver-plating). Sold only with the suit.'),
  ('ng-nx14-sea-demon', 2, 'CD-214 Blue-Green Forearm Lasers (2)', '2D6 M.D. per blast', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and anti-vehicle, secondarily hunting and defense. A short barrel under a lid above each wrist, made for use underwater and on the surface, and the answer to power armor too quick for a torpedo.'),
  ('ng-nx14-sea-demon', 3, 'CD-314 Vibro-Blade (left forearm)', '1D6 M.D.', 1, 'Melee; arm''s reach', 'Each attack counts as one melee action', NULL, NULL, 'Cutting and anti-monster, secondarily defense. A short retractable blade for gutting big fish and for close fighting. Silver plating is 2,000 credits (gear row ng-nx14-sea-demon-blade-silver-plating).'),
  ('ng-uelx49-silent-shadow', 1, 'Concealed Forearm Laser (1, shooting arm)', '2D6 M.D. per shot', 1, '2,000 ft (610 m); as an infrared rangefinder, two miles (3.2 km)', 'Each blast counts as one melee attack', 'Unlimited; draws on the suit''s power', NULL, 'Assault, secondarily defense. A light laser hidden in the right or left forearm, whichever the wearer shoots with.'),
  ('ng-uelx49-silent-shadow', 2, 'Concealed Spike and Climb Cord (1, other forearm)', '1 M.D. as a weapon', 1, '30 ft (9.1 m)', 'One; then the spike is recovered or cut loose', 'One, reusable', NULL, 'Climbing, secondarily a towline. A fired spike or grapnel trailing 30 ft (9.1 m) of cable that winds back into the arm; it can also hook a boat, ship or aircraft and tow the suit like a kite.'),
  ('ng-uelx49-silent-shadow', 3, 'Concealed Vibro-Short Swords (2, one per forearm)', '1D6 M.D.; +4 on a flying slash or stab', 1, 'Melee; arm''s reach', NULL, NULL, NULL, 'Assault, secondarily defense and a utility tool. An extendible short Vibro-Sword hidden in each forearm.'),
  ('ng-x40-storm-hammer', 1, 'NG-P40 Onslaught Particle Beam Cannon (cowl turret)', '1D6x10 M.D. per blast', 1, '1,800 ft (549 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Anti-armor and anti-robot, secondarily assault and anti-monster. Short-ranged for its power; the turret turns 360 degrees and elevates 30 degrees up or down. After 30 blasts it overheats and shuts down for 1D4+1 melee rounds.'),
  ('ng-x40-storm-hammer', 2, 'NG-M18 Shoulder Mounted Missile Launchers (2)', 'By missile; usually plasma (1D6x10 M.D.) or armor piercing (1D4x10 M.D.), any type fits', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4 or 6', '18, nine per launcher', NULL, 'Anti-armor, anti-aircraft and assault, secondarily anti-missile and defense. A second person reloads from behind and beside the suit, three melee rounds (45 seconds) for nine missiles.'),
  ('ng-x40-storm-hammer', 3, 'NG-MH140 Rail Gun (right forearm, with targeting laser)', 'Rail gun 1D6 M.D. single shot, 1D6x10 M.D. per 20-round burst; laser 1D6 M.D.', 1, '5,000 ft (1,524 m), both', 'Each shot or burst counts as one melee attack', '1,200-round drum on the back for 60 bursts, plus two 80-round canisters under the barrel for eight last-chance bursts; laser effectively unlimited', NULL, 'Anti-personnel, secondarily defense. A heavy housing that encloses the right hand and forearm, fired by the hand inside; its laser mainly ranges and targets but can fire for light damage.'),
  ('ng-x40-storm-hammer', 4, 'Multi-Tool Forearm (left)', 'Laser cutter 1D4x10 S.D.C., 1D4 M.D. or 2D6 M.D.; Vibro-Chainsaw 1D8 M.D. a cut, 2D8 M.D. held against a still target (two attacks)', 1, 'Arm''s reach; laser cutter 100 ft (30.5 m)', NULL, NULL, NULL, 'A repair tool for power armor and robots that serves for nearly anything. The gauntlet holds the laser cutter, a small M.D. chainsaw for wire, locks and walls, a macro camera (x20) beside the cutter, two dimmable LED lights (200 ft/61 m), and an elbow compartment usually holding 1-4 flares and two smoke grenades.'),
  ('ng-dx001-thunder-hound', 1, 'Forearm Vibro-Blades (2, silver-plated)', '1D6 M.D. per strike; double to creatures vulnerable to silver', 1, 'Melee; arm''s reach', NULL, NULL, NULL, 'Close combat, secondarily defense. A retractable blade hidden in each forearm, silver-plated as standard because the wearer is expected to fight the supernatural.'),
  ('ng-dx001-thunder-hound', 2, 'NG DX-011 Vibro-Chainsaw Sword (handheld)', 'Slash 4D6 M.D.; power strike pressed hard against the target 1D4x10 M.D., counting as two melee attacks', 1, 'Melee; 3 ft (0.9 m) beyond arm''s reach', 'Each attack counts as one melee action', 'Effectively unlimited on the UEL; one hour per standard E-Clip', NULL, 'Assault and anti-monster, secondarily anti-armor and defense. The suit''s signature weapon: a 3 ft (0.9 m) M.D.C. chainsaw blade whose teeth are silvered, used on Xiticix and other monsters and to cut through armored locks, hatches, hive walls and vehicle hulls, carried on the back or at the hip. No separate price is printed.'),
  ('ng-dx001-thunder-hound', 3, 'HX022 Forearm Laser (HX-002 only, right forearm)', '2D6 M.D.', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits; 80 blasts per charge on electric', NULL, 'Anti-aircraft and anti-missile, secondarily defense. The human model''s laser; the book places it, and the ion blaster, on the right forearm.'),
  ('ng-dx001-thunder-hound', 4, 'NG-HX122 Forearm Ion Blaster (HX-002 only, 1)', '3D6 M.D. per blast', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited on nuclear and Solid Oxide suits', NULL, 'Assault and anti-personnel, secondarily defense. A short-range ion blaster built into the human model''s forearm. Point and shoot.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-nx14-sea-demon', 'ng-uelx49-silent-shadow', 'ng-x40-storm-hammer', 'ng-dx001-thunder-hound');
SELECT 'their 36 locations are in' AS assertion, count(*) AS got, 36 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-nx14-sea-demon', 'ng-uelx49-silent-shadow', 'ng-x40-storm-hammer', 'ng-dx001-thunder-hound');
SELECT 'their 14 weapon entries are in' AS assertion, count(*) AS got, 14 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-nx14-sea-demon', 'ng-uelx49-silent-shadow', 'ng-x40-storm-hammer', 'ng-dx001-thunder-hound');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-nx14-sea-demon', 'ng-uelx49-silent-shadow', 'ng-x40-storm-hammer', 'ng-dx001-thunder-hound') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

